import { getNotificationPreference, toggleNotificationPreference } from './actions';

export default async function Home() {
  // Fetch the current notification preference
  // Using a demo userId - in a real app, this would come from authentication
  const userId = 'demo-user';
  const notificationsEnabled = await getNotificationPreference(userId);

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Settings</h1>
      <div style={{ marginTop: '2rem' }}>
        <h2>Notification Preferences</h2>
        <p>
          Notifications are currently:{' '}
          <strong style={{ color: notificationsEnabled ? 'green' : 'red' }}>
            {notificationsEnabled ? 'ON' : 'OFF'}
          </strong>
        </p>
        <form action={async () => {
          'use server';
          await toggleNotificationPreference(userId);
        }}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              fontSize: '1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '0.25rem',
              cursor: 'pointer'
            }}
          >
            Toggle Notifications
          </button>
        </form>
      </div>
    </main>
  );
}

